<?php
declare(strict_types=1);
require_once __DIR__.'/includes/web_orders.php';
$pdo=db();$token=trim((string)($_GET['token']??''));$s=$pdo->prepare("SELECT o.order_number,o.status,o.due_date,os.stage,c.name customer_name FROM cp_tracking_tokens tt INNER JOIN cp_orders o ON o.id=tt.order_id LEFT JOIN cp_order_status os ON os.order_id=o.id LEFT JOIN cp_customers c ON c.id=o.customer_id WHERE tt.token=? AND tt.active=1 LIMIT 1");$s->execute([$token]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r){http_response_code(404);exit('Seguimiento no encontrado.');}
$st=['pending'=>['Pedido recibido','Tu pedido fue registrado.'],'design'=>['Diseño','Estamos trabajando en el diseño.'],'approval'=>['Aprobación de diseño','Estamos listos para revisar.'],'ready'=>['Listo para entrega','Tu pedido está listo.'],'delivered'=>['Entregado','El pedido fue marcado como entregado.']];$current=(string)($r['stage']??'pending');
?>
<!doctype html><html lang="es-MX"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seguimiento <?=cp_web_h((string)$r['order_number'])?></title><link rel="stylesheet" href="<?=cp_web_h(cp_web_route('/assets/css/order-public-v1.css'))?>"></head><body><main class="op-wrap"><p class="op-kicker">SEGUIMIENTO</p><h1><?=cp_web_h((string)$r['order_number'])?></h1><p class="op-lead">Hola <?=cp_web_h((string)($r['customer_name']??''))?>.</p><section class="op-card"><span class="op-badge"><?=cp_web_h($st[$current][0]??'En proceso')?></span><p><?=cp_web_h($st[$current][1]??'En proceso')?></p><?php if($r['due_date']):?><small>Fecha compromiso: <?=cp_web_h(date('d/m/Y',strtotime($r['due_date'])))?></small><?php endif;?></section><div class="op-timeline"><?php foreach($st as $k=>$v):?><div class="<?=array_search($k,array_keys($st),true)<=array_search($current,array_keys($st),true)?'done':''?>"><b><?=cp_web_h($v[0])?></b><span><?=cp_web_h($v[1])?></span></div><?php endforeach;?></div></main></body></html>
